/* базовый слой — работает везде, где есть flexbox */
.card {
  background: #1b2340;
  border-radius: 14px;
  padding: 18px;
}

/* улучшение только для тех, кто поддерживает свойство */
@supports (backdrop-filter: blur(8px)) {
  .card {
    background: rgba(27, 35, 64, .62);
    backdrop-filter: blur(8px);
  }
}

/* autoprefixer сам добавит -webkit-backdrop-filter для Safari,
   если тот попал в browserslist. Руками префиксы писать не нужно. */

const images = document.querySelectorAll('img[data-src]');

if ('IntersectionObserver' in window) {
  const observer = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (!entry.isIntersecting) return;
      const img = entry.target;
      img.src = img.dataset.src;
      observer.unobserve(img);
    });
  });

  images.forEach(function (img) { observer.observe(img); });
} else {
  // фолбэк: без наблюдателя просто грузим всё сразу
  images.forEach(function (img) { img.src = img.dataset.src; });
}

