}

/* улучшение оберните в @supports (display: grid) */

exercises.solution:
.gallery {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

@supports (display: grid) {
  .gallery {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
  }
}
